        return ADCS_E_NULL;
    }

    if ((!isfinite(estimated->x)) || (!isfinite(estimated->y)) || (!isfinite(estimated->z)) ||
        (!isfinite(estimated->w)) ||
        (!isfinite(target->x)) || (!isfinite(target->y)) || (!isfinite(target->z)) ||
        (!isfinite(target->w))) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    adcs_quat_t norm_est, norm_target;
    if (adcs_quat_normalize(estimated, &norm_est) != ADCS_OK) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_quat_normalize(target, &norm_target) != ADCS_OK) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    adcs_quat_t q_est_conj = adcs_quat_conjugate(&norm_est);
    adcs_quat_t q_err = adcs_quat_multiply(&norm_target, &q_est_conj);

    if (q_err.w < 0.0) {
        q_err.w = -q_err.w;
        q_err.x = -q_err.x;
        q_err.y = -q_err.y;
        q_err.z = -q_err.z;
    }

    adcs_vec3_t s_vec = {q_err.x, q_err.y, q_err.z};
    double s = adcs_vec3_norm(&s_vec);
    double w = q_err.w;

    if (s <= 1e-12) {
        *error = adcs_vec3_scale(&s_vec, 2.0);
    } else {
        double angle = 2.0 * atan2(s, w);
        double scale = angle / s;
        *error = adcs_vec3_scale(&s_vec, scale);
    }

    return ADCS_OK;
}

